/* Kinyarwanda Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Emmanuel": "God with us — Hebrew, via Christianity", "Jean": "God is gracious — Hebrew Yohanan, via French", "Marie": "Widespread feminine name, frequently combined as Marie Claire or Marie Chantal.", "Divine": "divine, heavenly — French", "Innocent": "innocent, harmless — Latin, via French", "Pacifique": "peaceful, peacemaking — French", "Kagame": "Rwandan family name borne by President Paul Kagame.", "Habimana": "A common Rwandan family name built on Imana, God.", "Bizimana": "A widely used Rwandan family name expressing faith.", "Nkurunziza": "Family name of the region, borne by Burundian president Pierre Nkurunziza."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Emmanuel';
console.log(lookup(q));

